import{_ as o,l as i,o as e,c as n,v as l,p as s,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"尾调用优化","description":"","frontmatter":{"title":"尾调用优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tail-call-opt.md","filePath":"cs/tail-call-opt.md","lastUpdated":1789023840000}'),h={name:"cs/tail-call-opt.md"};function m(u,a,_,f,C,T){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="尾调用优化" tabindex="-1">尾调用优化 <a class="header-anchor" href="#尾调用优化" aria-label="Permalink to &quot;尾调用优化&quot;">​</a></h1><div class="epigraph"><p>若 `call` 的结果就是当前函数的返回值，且当前帧不再被需要，则可释放帧并把调用改成跳转。空间从线性变成常量。</p><footer>—— 据 Steele, Debunking the &#39;Expensive Procedure Call&#39; Myth；Scheme 报告对 proper tail calls；Appel, Compiling with Continuations 整理</footer></div><p>上一课<a href="/cs/inlining-heuristics">内联</a>用复制换开销。缺口是<strong>不复制</strong>的调用优化：尾调用（TCO）。Scheme 要求 proper tail calls；C 不保证。本课钉何时合法，与<a href="/cs/trampolining">蹦床</a> 后课对照只点名。不写 CPS 变换全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>return f(x)</code> 在调用后当前函数无工作。栈上若仍留帧，递归 <code>f</code> 会爆栈。优化：调整参数、<code>jmp f</code>。缺口是<strong>帧与调试/异常</strong>是否还需要当前帧（析构、清理）。</p><p>C++：析构函数使许多「看起来像尾」的调用不是尾。必须先跑清理则不能 TCO，或变成先清理再跳（仍可能）。</p><h3 id="尾递归不是全部尾调用" tabindex="-1">尾递归不是全部尾调用 <a class="header-anchor" href="#尾递归不是全部尾调用" aria-label="Permalink to &quot;尾递归不是全部尾调用&quot;">​</a></h3><p>尾递归是 callee 为自身；TCO 对任意尾位置调用。互递归同样可跳转。不要只教「编译器把递归变循环」这一特例。</p><p><span class="marginnote">Steele 1977。R*RS proper tail calls。Appel 指出 CPS 后所有调用是尾。本课 IR 级：<code>ret (call ...)</code> 形态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>识别：调用结果立即返回，无待办副作用。ABI：callee 与 caller 约定兼容（参数寄存器），否则要垫片。不同函数尾调用可能要调整栈参数区。</p>',11)),(e(),s(d,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RET%5B%22return%20f(args)%22%5D%20--%3E%20CHK%5B%22%E6%97%A0%E5%BE%85%E6%B8%85%E7%90%86%22%5D%0A%20%20CHK%20--%3E%20JMP%5B%22jmp%20f%22%5D%0A%20%20JMP%20--%3E%20STK%5B%22%E5%A4%8D%E7%94%A8%E6%88%96%E5%BC%B9%E5%87%BA%E5%B8%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>与内联：小的尾递归可内联成循环；大的只 TCO。不要二者都做导致体爆炸再 TCO 无意义。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>诊断：语言若保证 TCO，漏优化是 bug；C 则是质量。调试器：帧消失，backtrace 变短——DWARF 可选用虚拟帧。不要在必须精确栈展开的异常路径上静默 TCO 而不更新 unwind。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 CPS。后课默认：尾位置调用可变成跳转。下一课逃逸分析：堆分配能否改栈，与帧寿命相关。</p><p>也不把 TCO 当异步协程的定义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>尾调用：复用帧，call 变 jmp。</li><li>清理、ABI、异常表限制合法性。</li><li>尾递归是特例；互递归同样适用。</li><li>出处：Steele；Scheme 报告；Appel。</li></ul>',8))])}const E=o(h,[["render",m]]);export{S as __pageData,E as default};
